  <form class="product-toolbar" method="get"><input type="hidden" name="page" value="commercial_product_library"><input type="search" name="q" value="<?= cc_h((string)($_GET['q']??'')) ?>" placeholder="型号 / 系列 / 类别 / 功率 / 参数"><select name="category"><option value="">分类</option><?php foreach($catalog['categories'] as $c): ?><option value="<?= cc_h($c['category']) ?>"><?= cc_h($c['category']) ?></option><?php endforeach; ?></select><select name="status"><option value="">状态</option><option>可报价</option><option>开发中</option><option>停售</option></select><select name="power"><option value="">功率</option></select><a href="?page=commercial_product_library&mode=list">列表</a></form>
  <?php if($catalog['status']!=='available'): ?><section class="login-notice"><strong>当前账号无法读取产品库</strong></section><?php else: ?><section class="product-grid product-library-grid"><?php foreach($shown as $row): $cost=$row['bom_cost']??null; ?><article class="library-card" data-product-detail data-model="<?= cc_h($row['model_no']) ?>"><div class="library-thumb"><?php $image=cc_legacy_asset_url($row['image_path']); if($image): ?><img src="<?= cc_h($image) ?>" alt="" loading="lazy"><?php else: ?><span>NO IMAGE</span><?php endif; ?></div><div><h3><?= cc_h($row['model_no']) ?></h3><small><?= cc_h($row['series_name']) ?> · <?= cc_h($row['category']) ?></small><p class="product-size">尺寸：<?= cc_h($row['dim_outer_d']?:'—') ?> × <?= cc_h($row['dim_height']?:'—') ?></p><strong class="product-price">参考报价：USD <?= $cost===null?'—':number_format((float)$cost,2) ?></strong><footer><span>状态：<?= cc_h($row['status']) ?></span><button type="button" class="text-button">查看详情</button></footer></div></article><?php endforeach; ?></section><?php endif; ?>
